INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (1, '春季环湖骑行活动圆满结束', '4月15日，俱乐部组织的春季环湖骑行活动圆满结束。本次活动共有58名会员参与，全程120公里，途经东湖、西山、北岭等多个风景名胜。活动中大家互相帮助，展现了良好的团队协作精神。多位新会员表示通过活动更好地融入了俱乐部大家庭。', '俱乐部活动,最新动态', '58名会员参与，全程120公里，团队协作精神突出', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/00876e2d-b751-4710-bddd-e36a704c7b4b.png', '活动,动态', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (2, '川藏线长途骑行队凯旋归来', '经过15天的长途骑行，俱乐部川藏线骑行队全员安全返回。12名队员克服高原反应、恶劣天气等困难，成功完成2400公里的挑战。队长张明表示："这次经历让我们更加热爱骑行，也见证了团队的力量。"俱乐部将在下周举办分享会，欢迎大家参加。', '俱乐部活动,最新动态', '15天2400公里，12名队员挑战川藏线成功', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/4af1e4f5-a330-4fa8-9c92-845b14adc46d.png', '活动,推荐', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (3, '俱乐部年度骑行大赛报名启动', '2025年度"极速挑战"骑行大赛将于6月举行。比赛设置竞速赛、耐力赛、技巧赛三个项目，欢迎各级别会员报名参加。冠军将获得价值5000元的改装基金和年度荣誉勋章。报名截止日期为5月20日，名额有限，先到先得！', '俱乐部活动', '年度骑行大赛，冠军奖励5000元改装基金', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/f624d3d7-e741-46a4-9242-1d19b1aa8564.png', '活动,推荐', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (4, '会员突破500人里程碑达成', '截至本月，俱乐部注册会员已突破500人大关！从最初的十几个人到如今的大家庭，感谢每一位骑友的支持和信任。为庆祝这一里程碑，俱乐部将举办会员答谢活动，所有会员享受培训课程8折优惠。我们将继续提供更优质的服务和活动。', '俱乐部活动,最新动态', '会员突破500人，举办答谢活动和优惠', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/223a8cbf-df20-4990-b0ba-a3de7d4a9596.png', '动态', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (5, '山路压弯技巧实战分享', '资深教练李华分享山路骑行压弯技巧：①入弯前降速至合适档位；②视线提前看向出弯点；③车身倾斜角度要循序渐进；④出弯时平稳加油门。他强调"慢进快出"的原则，建议新手先在封闭场地练习基本功。下周六将开设专项训练营，欢迎报名。', '骑行技巧,最新动态', '压弯四大要点，新手必看的实战技巧', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/707abce0-3f4d-49b4-b3f6-a157f943e078.png', '教学,推荐', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (6, '雨天骑行安全指南发布', '雨季来临，俱乐部发布雨天骑行安全指南：①降低车速，保持安全距离；②避免急刹车和大幅度转向；③优先选择排水良好的路段；④穿着防水骑行服，确保视野清晰；⑤积水路段谨慎通过。教练组提醒：能见度低于50米时建议暂停骑行。', '骑行技巧,安全知识', '雨天骑行五大要点，保障安全第一', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/f76efe22-28f1-4cab-bc8c-814856ade6b4.png', '安全,教学', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (7, '长途骑行装备清单推荐', '计划长途骑行？这份装备清单请收好：①必备：头盔、手套、骑行服、护具；②工具：补胎工具、扳手组、备用零件；③应急：急救包、应急食品、充电宝；④导航：GPS设备或手机支架。教练建议提前规划路线，每骑行2小时休息15分钟。', '骑行技巧', '长途骑行必备装备清单和注意事项', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/0a00bda5-05ed-4d19-be00-fc8ff0b2c4c7.png', '教学', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (8, '高速公路骑行安全规范', '俱乐部安全部发布高速公路骑行规范：①排量250cc以上车辆方可上高速；②速度保持在60-100km/h；③禁止占用应急车道；④保持车距，避免长时间骑行；⑤夜间骑行需开启示廓灯。违规骑行不仅危险，还将面临扣分罚款。', '安全知识,最新动态', '高速公路骑行五大规范，安全第一', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/3d1565bf-8959-4a1b-8942-154f8199e98c.png', '安全,教学', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (9, '防御性驾驶理念培训通知', '本周六下午3点，俱乐部将举办防御性驾驶理念培训。课程内容包括：①预判其他车辆行为；②保持安全车距；③避免盲区骑行；④应对突发情况的技巧。培训免费，提供培训证书。名额仅限50人，请提前在群内报名。', '安全知识', '防御性驾驶培训，提升安全意识', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/55086cc7-d558-4091-9427-02625855da1f.png', '安全,动态', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (10, '夏季高温骑行注意事项', '夏季高温天气骑行需特别注意：①选择透气性好的骑行服；②随身携带充足的水分；③避开中午12点至下午3点的高温时段；④定期检查轮胎胎压；⑤感到头晕乏力应立即停车休息。教练提醒：中暑是夏季骑行的主要风险之一。', '安全知识,最新动态', '夏季骑行五大注意事项和应急措施', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/e47b3c1e-cb1e-4d81-a9ab-3fd05d705f48.png', '安全', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (11, '摩托车日常保养基础教程', '教练手把手教你日常保养：①每500公里检查链条松紧度并润滑；②每1000公里更换机油和滤芯；③定期清洁空气滤清器；④检查刹车片磨损情况；⑤轮胎气压保持标准值。本周日上午10点开设实操课程，自带工具即可参加。', '车辆保养', '日常保养五步法，延长爱车寿命', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/45fb4149-6eef-433a-b744-35ac5c3c8301.png', '保养,教学', 0, '2025-12-10 07:58:32', '2025-12-12 09:30:24', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (12, '换季保养专项服务优惠', '春季换季保养套餐限时优惠！包含：①全车深度清洁；②机油机滤更换；③链条调整润滑；④刹车系统检查；⑤电瓶检测。原价680元，会员价仅需480元。活动截止到本月底，预约请联系服务部。提供免费上门取车服务。', '车辆保养,最新动态', '换季保养套餐，会员专享优惠价480元', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/20c7b12d-de58-475f-becb-eb799fbba91b.png', '保养,动态', 0, '2025-12-10 07:58:32', '2025-12-11 03:06:00', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (13, '会员改装案例：川崎Z900改装分享', '会员王强分享他的川崎Z900改装经历：更换阿克拉波维奇排气、升级欧林斯避震、安装防摔部件、改装LED灯组。总投入约3万元，动力提升明显，操控更加精准。他强调："改装需合法合规，优先考虑安全性。"俱乐部将在下月举办改装展示会。', '会员风采', '川崎Z900改装案例，3万元打造性能利器', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/ba646fc4-1db5-4be4-9735-4eb68e4ade95.png', '推荐', 0, '2025-12-10 07:58:32', '2025-12-11 03:05:53', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (14, '新会员入会体验分享', '新会员李明分享入会感受："加入俱乐部一个月，参加了两次骑行活动和一次技巧培训，收获满满。教练很专业，会员很热情，真正感受到了大家庭的温暖。特别是新手训练营，让我从菜鸟变成了敢上路的骑手。强烈推荐给刚拿驾照的朋友！"', '会员风采,最新动态', '新会员真实体验，从菜鸟到独立骑手', 1, 'https://java-ai-178.oss-cn-beijing.aliyuncs.com/HBBTJ/news/images/4a8521d3-f672-40ec-945c-1486c59bbfd3.png', '动态,推荐', 0, '2025-12-10 07:58:32', '2025-12-11 03:05:47', 'approved', null, null);
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time, status, creator_id, creator_name) VALUES (15, '新手训练营第五期火热招生', '针对刚拿到驾照的新手，推出为期一周的封闭式训练营。课程包含：①基础操作（起步、换挡、刹车）；②安全意识培养；③道路规则讲解；④实际路况模拟。资深教练一对一指导，提供训练车辆，包教包会！现在报名享受早鸟价8折优惠。', '最新动态', '新手训练营招生，资深教练一对一指导', 1, 'https://picsum.photos/id/22/360/180', '动态,教学', 0, '2025-12-10 07:58:32', '2025-12-10 08:04:07', 'approved', null, null);
